class_name BTSelector
extends BTNode

@export var children: Array[BTNode] = []

func tick(blackboard: Dictionary) -> int:
	for child in children:
		if child == null:
			continue
		var result = child.tick(blackboard)
		if result == SUCCESS:
			return SUCCESS
		elif result == RUNNING:
			return RUNNING
		# If FAILURE, continue to next child
	return FAILURE

class_name BTSequence
extends BTNode

@export var children: Array[BTNode] = []

func tick(blackboard: Dictionary) -> int:
	for child in children:
		if child == null:
			continue
		var result = child.tick(blackboard)
		if result == FAILURE:
			return FAILURE
		elif result == RUNNING:
			return RUNNING
		# If SUCCESS, continue to next child
	return SUCCESS

class_name BTInverter
extends BTNode

@export var child: BTNode

func tick(blackboard: Dictionary) -> int:
	if child == null:
		return FAILURE
	var result = child.tick(blackboard)
	if result == SUCCESS:
		return FAILURE
	elif result == FAILURE:
		return SUCCESS
	else:
		return RUNNING

class_name IsHealthy
extends BTAction

func tick(blackboard: Dictionary) -> int:
	var health = blackboard.get("health", 0)
	var threshold = blackboard.get("healthy_threshold", 0)
	if health >= threshold:
		return SUCCESS
	else:
		return FAILURE

class_name ChasePlayer
extends BTAction

func tick(blackboard: Dictionary) -> int:
	blackboard["action"] = "chase"
	var distance = blackboard.get("distance_to_player", 0.0)
	var attack_range = blackboard.get("attack_range", 0.0)

	if distance <= attack_range:
		return SUCCESS

	var chase_speed = blackboard.get("chase_speed", 0.0)
	blackboard["distance_to_player"] = distance - chase_speed
	return RUNNING

class_name AttackIfInRange
extends BTAction

func tick(blackboard: Dictionary) -> int:
	var distance = blackboard.get("distance_to_player", 0.0)
	var attack_range = blackboard.get("attack_range", 0.0)

	if distance <= attack_range:
		blackboard["action"] = "attack"
		blackboard["last_attack_damage"] = blackboard.get("attack_damage", 0)
		return SUCCESS
	else:
		return FAILURE
